function solve(follows, tweets, userId) {
  const followed = new Set();
  for (const row of follows) {
    if (row.length < 2) continue;
    if (row[0] === userId) followed.add(row[1]);
  }
  const picked = [];
  for (let i = 0; i < tweets.length; i++) {
    const row = tweets[i];
    if (row.length < 2) continue;
    const author = row[0];
    if (author === userId || followed.has(author)) picked.push(i);
  }
  picked.sort((a, b) => b - a);
  const res = [];
  const limit = Math.min(10, picked.length);
  for (let i = 0; i < limit; i++) res.push(tweets[picked[i]][1]);
  return res;
}

function solve(follows, tweets, userId) {
  const followed = new Set();
  for (const row of follows) {
    if (row.length < 2) continue;
    if (row[0] === userId) followed.add(row[1]);
  }
  const heap = [];
  const swap = (i, j) => {
    const held = heap[i];
    heap[i] = heap[j];
    heap[j] = held;
  };
  const siftUp = (i) => {
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent][0] <= heap[i][0]) break;
      swap(parent, i);
      i = parent;
    }
  };
  const siftDown = (i) => {
    for (;;) {
      let smallest = i;
      const left = 2 * i + 1;
      const right = 2 * i + 2;
      if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
      if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
      if (smallest === i) break;
      swap(smallest, i);
      i = smallest;
    }
  };
  for (let i = 0; i < tweets.length; i++) {
    const row = tweets[i];
    if (row.length < 2) continue;
    const author = row[0];
    if (author !== userId && !followed.has(author)) continue;
    heap.push([i, row[1]]);
    siftUp(heap.length - 1);
    if (heap.length > 10) {
      heap[0] = heap[heap.length - 1];
      heap.pop();
      siftDown(0);
    }
  }
  const out = [];
  while (heap.length > 0) {
    out.push(heap[0][1]);
    heap[0] = heap[heap.length - 1];
    heap.pop();
    siftDown(0);
  }
  out.reverse();
  return out;
}
